-- V6: 列级对齐——V1-V4/V5 所建表与实体期望列的差异补齐（列定义取自 sql/ 手工链 DDL）
SET FOREIGN_KEY_CHECKS=0;
ALTER TABLE `ai_avatar` ADD COLUMN ratingCount    int           default 0                 not null comment '评分人数';
ALTER TABLE `ai_avatar` ADD COLUMN sort           int           default 0                 not null comment '排序，数字越小排序越靠前';
ALTER TABLE `ai_avatar_chat_history` ADD COLUMN sessionName varchar(512)                       null comment '会话总结标题';
ALTER TABLE `ai_avatar_chat_history` ADD COLUMN messageType varchar(32)                        not null comment '消息类型：user/ai';
ALTER TABLE `course` ADD COLUMN subtitle       varchar(512)                             null comment '课程副标题';
ALTER TABLE `course` ADD COLUMN coverImage     varchar(1024)                            null comment '封面图片URL';
ALTER TABLE `course` ADD COLUMN originalPrice  decimal(10, 2) default 0.00              null comment '原价';
ALTER TABLE `course` ADD COLUMN courseType     tinyint        default 0                 not null comment '课程类型：0-公开课，1-付费课，2-会员课';
ALTER TABLE `course` ADD COLUMN difficulty     tinyint        default 1                 not null comment '难度等级：1-入门，2-初级，3-中级，4-高级，5-专家';
ALTER TABLE `course` ADD COLUMN status         tinyint        default 0                 not null comment '状态：0-未发布，1-已发布，2-已下架';
ALTER TABLE `course` ADD COLUMN teacherId      bigint                                   not null comment '讲师id';
ALTER TABLE `course` ADD COLUMN totalDuration  int            default 0                 not null comment '总时长(分钟)';
ALTER TABLE `course` ADD COLUMN totalChapters  int            default 0                 not null comment '总章节数';
ALTER TABLE `course` ADD COLUMN totalSections  int            default 0                 not null comment '总小节数';
ALTER TABLE `course` ADD COLUMN studentCount   int            default 0                 not null comment '学习人数';
ALTER TABLE `course` ADD COLUMN ratingScore    decimal(2, 1)  default 0.0               not null comment '评分，1-5分';
ALTER TABLE `course` ADD COLUMN ratingCount    int            default 0                 not null comment '评分人数';
ALTER TABLE `course` ADD COLUMN requirements   text                                     null comment '学习要求';
ALTER TABLE `course` ADD COLUMN objectives     text                                     null comment '学习目标';
ALTER TABLE `course` ADD COLUMN targetAudience text                                     null comment '目标受众';
ALTER TABLE `course` ADD COLUMN adminId        bigint                                   not null comment '创建管理员id';
ALTER TABLE `course_chapter` ADD COLUMN title       varchar(256)                       not null comment '章节标题';
ALTER TABLE `course_chapter` ADD COLUMN description text                               null comment '章节描述';
ALTER TABLE `course_chapter` ADD COLUMN sort        int      default 0                 not null comment '排序，数字越小排序越靠前';
ALTER TABLE `course_chapter` ADD COLUMN adminId     bigint                             not null comment '创建管理员id';
ALTER TABLE `course_chapter` ADD COLUMN isDelete    tinyint  default 0                 not null comment '是否删除';
ALTER TABLE `private_chat_session` ADD COLUMN isDelete        TINYINT  DEFAULT 0                 NOT NULL COMMENT '是否删除：0-否，1-是';
ALTER TABLE `private_message` ADD COLUMN isDelete    TINYINT  DEFAULT 0                 NOT NULL COMMENT '是否删除：0-否，1-是';
ALTER TABLE `user_course_progress` ADD COLUMN sectionId     bigint                             not null comment '小节id';
ALTER TABLE `user_course_progress` ADD COLUMN progress      int      default 0                 not null comment '学习进度(百分比)';
ALTER TABLE `user_course_progress` ADD COLUMN watchDuration int      default 0                 not null comment '观看时长(秒)';
ALTER TABLE `user_course_progress` ADD COLUMN lastPosition  int      default 0                 not null comment '上次观看位置(秒)';
ALTER TABLE `user_course_progress` ADD COLUMN isCompleted   tinyint  default 0                 not null comment '是否完成：0-否，1-是';
ALTER TABLE `user_course_progress` ADD COLUMN completedTime datetime                           null comment '完成时间';
SET FOREIGN_KEY_CHECKS=1;
